<template>
  <div class="ai-page">
    <section class="page-heading"><div><p class="eyebrow">AI PHOTOGRAPHY WORKBENCH</p><h1>让照片先被理解，<br /><em>再被发现。</em></h1><p>为云端资产生成摄影元数据，人工确认后即可用自然语言找到想要的照片。</p></div><a-button @click="router.push('/')">返回图库</a-button></section>
    <section class="search-panel"><div class="panel-icon"><RobotOutlined /></div><div class="search-content"><h2>用一句话搜索你的照片</h2><p>试试“黄昏的海边”“适合做封面的横构图”或“35mm 镜头拍摄的人像”。</p><a-input-search v-model:value="query" size="large" enter-button="开始检索" placeholder="描述你想找的摄影画面" :loading="searching" @search="doSearch" /></div></section>
    <a-row :gutter="22" class="workspace"><a-col :xs="24" :lg="9"><section class="tool-panel"><div class="panel-title"><span class="number">01</span><div><h2>生成摄影编目</h2><p>选择一张图片，让 AI 识别主体、场景、光线和构图。</p></div></div><a-input v-model:value="pictureId" size="large" style="width:100%" placeholder="输入图片 ID" /><a-button type="primary" block size="large" :loading="cataloging" @click="catalog">生成元数据</a-button><a-alert v-if="task" class="task-alert" :type="task.status==='FAILED'?'error':'success'" show-icon :message="task.status==='SUCCESS'?'编目完成':'任务已提交'" :description="task.errorMessage || '可以在右侧查看检索结果，或打开元数据确认。'" /></section><section class="tips-panel"><BulbOutlined /><div><strong>工作建议</strong><p>先上传清晰的原图，再进行编目。AI 结果会保存到图片资产中，之后可以重复检索。</p></div></section></a-col><a-col :xs="24" :lg="15"><section class="result-panel"><div class="result-heading"><div><span class="number">02</span><h2>检索结果</h2></div><span v-if="hasSearched">找到 {{ results.length }} 张相关图片</span></div><a-list v-if="results.length" :data-source="results" item-layout="horizontal"><template #renderItem="{ item }"><a-list-item><div class="result-item"><div class="result-thumb"><img v-if="item.thumbnailUrl || item.url" :src="item.thumbnailUrl || item.url" alt="" /><PictureOutlined v-else /></div><div class="result-info"><strong>图片 #{{ item.id ?? item }}</strong><span>{{ item.name || '摄影资产' }}</span><small>已通过权限过滤 · 点击查看摄影元数据</small></div><a-button type="text" @click="loadMeta(parseId(item.id ?? item))">查看元数据</a-button></div></a-list-item></template></a-list><a-empty v-else class="result-empty" :description="hasSearched?'没有匹配的摄影资产':'输入摄影语义开始检索'"><template #image><SearchOutlined /></template></a-empty></section></a-col></a-row>
    <a-drawer v-model:open="metaOpen" title="摄影元数据" placement="right" :width="380"><a-spin :spinning="metaLoading"><a-descriptions v-if="meta" bordered :column="1"><a-descriptions-item label="拍摄方向">{{ meta.orientation || '未识别' }}</a-descriptions-item><a-descriptions-item label="主体标签">{{ meta.subjectTags || '未识别' }}</a-descriptions-item><a-descriptions-item label="场景标签">{{ meta.sceneTags || '未识别' }}</a-descriptions-item><a-descriptions-item label="光线标签">{{ meta.lightTags || '未识别' }}</a-descriptions-item><a-descriptions-item label="构图标签">{{ meta.compositionTags || '未识别' }}</a-descriptions-item><a-descriptions-item label="质量评分">{{ meta.qualityScore ?? '未评分' }}</a-descriptions-item><a-descriptions-item label="确认状态">{{ meta.confirmed ? '人工已确认' : '待人工确认' }}</a-descriptions-item></a-descriptions><a-empty v-else description="暂无摄影元数据" /></a-spin></a-drawer>
  </div>
</template>
<script setup lang="ts">
import { ref } from 'vue'; import { message } from 'ant-design-vue'; import { BulbOutlined, PictureOutlined, RobotOutlined, SearchOutlined } from '@ant-design/icons-vue'; import { useRouter } from 'vue-router'; import { catalogPicture, getAiMeta, searchAi } from '@/api/photoCommunity'; import { parseId } from '@/utils'
const router=useRouter();const query=ref('');const searching=ref(false);const hasSearched=ref(false);const results=ref<any[]>([]);const pictureId=ref<string>('');const task=ref<any>();const cataloging=ref(false);const meta=ref<any>();const metaOpen=ref(false);const metaLoading=ref(false)
async function doSearch(){if(!query.value.trim())return;searching.value=true;hasSearched.value=true;try{const res:any=await searchAi(query.value.trim());if(res.data.code===0)results.value=res.data.data||[];else message.error(res.data.message)}catch{message.error('AI 检索暂时不可用')}finally{searching.value=false}}
async function catalog(){if(!pictureId.value){message.warning('请输入图片 ID');return}cataloging.value=true;try{const res:any=await catalogPicture(pictureId.value);if(res.data.code===0){task.value=res.data.data;message.success('摄影编目任务已提交')}else message.error(res.data.message)}catch{message.error('编目任务提交失败')}finally{cataloging.value=false}}
async function loadMeta(id?: string){if(!id){message.warning('图片 ID 无效');return}metaLoading.value=true;metaOpen.value=true;try{const res:any=await getAiMeta(id);if(res.data.code===0)meta.value=res.data.data;else message.error(res.data.message)}finally{metaLoading.value=false}}
</script>
<style scoped>
.ai-page{max-width:1180px;margin:0 auto}.page-heading{display:flex;justify-content:space-between;gap:20px;align-items:start;margin-bottom:28px}.eyebrow{margin:0 0 10px;color:#668473;font-size:11px;font-weight:600;letter-spacing:2px}.page-heading h1{margin:0;color:#20322e;font-size:38px;line-height:1.18}.page-heading h1 em{color:#568164;font-style:normal}.page-heading p:not(.eyebrow){color:#748078;line-height:1.7}.search-panel{display:flex;gap:18px;padding:26px 30px;margin-bottom:22px;background:#eaf2ec;border:1px solid #dce9df;border-radius:8px}.panel-icon{display:grid;place-items:center;width:46px;height:46px;flex:0 0 46px;border-radius:8px;background:#d7e9da;color:#4d7a5d;font-size:22px}.search-content{flex:1}.search-content h2{margin:0 0 5px;color:#304c3a;font-size:18px}.search-content p{margin:0 0 14px;color:#748078;font-size:13px}.tool-panel,.result-panel,.tips-panel{padding:24px;background:#fff;border:1px solid #e1e9e2;border-radius:8px}.tool-panel :deep(.ant-btn){margin-top:14px}.panel-title,.result-heading>div{display:flex;gap:12px;align-items:start;margin-bottom:20px}.number{color:#7da088;font-size:12px;letter-spacing:1px}.panel-title h2,.result-heading h2{margin:0 0 5px;color:#304c3a;font-size:18px}.panel-title p{margin:0;color:#87938b;font-size:13px;line-height:1.6}.task-alert{margin-top:18px}.tips-panel{display:flex;gap:12px;margin-top:14px;background:#f5f8f5;color:#688171;font-size:18px}.tips-panel strong{display:block;color:#45644f;font-size:13px}.tips-panel p{margin:5px 0 0;color:#829087;font-size:12px;line-height:1.6}.result-panel{min-height:390px}.result-heading{display:flex;justify-content:space-between;align-items:start;border-bottom:1px solid #edf1ee;padding-bottom:14px}.result-heading>div{margin:0}.result-heading>span{color:#87938b;font-size:12px}.result-item{display:flex;align-items:center;gap:14px;width:100%}.result-thumb{display:grid;place-items:center;width:56px;height:56px;flex:0 0 56px;overflow:hidden;border-radius:6px;background:#edf4ee;color:#6b8c74;font-size:22px}.result-thumb img{width:100%;height:100%;object-fit:cover}.result-info{display:grid;gap:3px;flex:1;min-width:0}.result-info strong{color:#355443}.result-info span{color:#617269;font-size:13px}.result-info small{color:#9aa59e;font-size:11px}.result-empty{padding:70px 0}.result-empty :deep(.ant-empty-image){font-size:32px;color:#7da088}@media(max-width:640px){.page-heading{display:block}.page-heading .ant-btn{margin-top:10px}.search-panel{padding:20px}.result-item .ant-btn{padding-inline:4px;font-size:12px}}
</style>
